  "news_id": "N:doc-5",
  "company_id": "U_19717",
  "headline": "Продление запрета на экспорт бензина стабилизирует ваши закупочные цены до конца года",
  "impact_type": "mixed",
  "importance": "medium",
  "confidence": "medium",
  "what_happened": [
    {"text": "Правительство продлило временный запрет на экспорт бензина для производителей до 31 декабря.", "origin": "fact", "source_ids": ["N:doc-5"]},
    {"text": "По оценке властей, мера должна снизить оптовые цены на топливо на внутреннем рынке; для сетей АЗС это может означать стабилизацию закупочных цен.", "origin": "fact", "source_ids": ["N:doc-5"]}
  ],
  "why_it_matters": [
    {"text": "Основной вид деятельности вашей компании — розничная торговля моторным топливом, а ключевое сырьё — бензин и дизельное топливо от НПЗ и нефтебаз: запрет экспорта напрямую влияет на цены ваших закупок.", "origin": "ai", "source_ids": ["F:MAINOKVED_NAME", "F:RAW_MATERIALS", "F:KEY_SUPPLIERS", "N:doc-5"]},
    {"text": "Ваши поставщики — нефтепереработка и оптовая торговля топливом — остаются в рынке с ограниченным экспортом, поэтому рост оптовых цен до конца года, вероятно, сдерживается; маржа АЗС может стабилизироваться.", "origin": "ai", "source_ids": ["P:U_9000006", "P:U_9000007", "N:doc-5"]},
    {"text": "Ваши клиенты — автовладельцы и транспортные компании — чувствительны к розничным ценам на топливо; стабильные закупочные цены снижают риск ценового давления на спрос.", "origin": "ai", "source_ids": ["F:KEY_CLIENTS", "P:U_9000008", "N:doc-5"]}
  ],
  "consequences": [
    {"text": "До 31 декабря закупочные цены на бензин, вероятно, стабильнее — предсказуемее платёжный календарь по поставщикам-нефтебазам и НПЗ.", "kind": "opportunity", "level": "medium", "horizon": "short", "origin": "ai", "source_ids": ["N:doc-5", "P:U_9000006", "P:U_9000007"]},
    {"text": "После 31 декабря режим экспорта может измениться: риск скачка оптовых цен и разрыва в марже при продлении или отмене запрета.", "kind": "risk", "level": "medium", "horizon": "medium", "origin": "ai", "source_ids": ["N:doc-5"]},
    {"text": "По оценке Альфа-Банка, спрос в розничной торговле замедляется на пике потребления — даже при стабильных закупочных ценах рост выручки АЗС может охладиться.", "kind": "factor", "level": "medium", "horizon": "medium", "origin": "ai", "source_ids": ["A:BA-16:0", "F:MAINOKVED_CODE"]}
  ],
  "actions": [
    {"text": "Зафиксировать график закупок топлива у нефтебаз и НПЗ на период до конца года, пока цены сдержаны запретом экспорта.", "type": "action", "bank_product": null, "source_ids": ["N:doc-5", "P:U_9000006", "P:U_9000007"]},
    {"text": "Сценарий: если запрет не продлят после 31 декабря и оптовые цены вырастут, — пересчитать план денежных потоков и лимиты на закупки на первый квартал.", "type": "scenario", "bank_product": null, "source_ids": ["N:doc-5"]},
    {"text": "Вопрос для анализа: какая доля закупок приходится на контракты с фиксированной ценой и как быстро поставщики перекладывают рост оптовых цен в ваши условия.", "type": "question", "bank_product": null, "source_ids": ["F:KEY_SUPPLIERS"]}
  ],
  "bank_view": [
    {"text": "Альфа-Банк отмечает, что ожидания роста товарного импорта существенно пересмотрены вверх (рост на 11% г/г, прогноз $340 млрд), что говорит о восстановлении доли импорта к ВВП.", "origin": "bank", "source_ids": ["A:BA-16:0"]},
    {"text": "По прогнозу банка на 2026 год, объёмы экспорта не пересматриваются ($480 млрд): дополнительные доходы могут не реализоваться из-за логистики и санкционных рисков.", "origin": "bank", "source_ids": ["A:BA-17:0"]}
  ],
  "company_features_used": ["F:MAINOKVED_NAME", "F:MAINOKVED_CODE", "F:RAW_MATERIALS", "F:KEY_SUPPLIERS", "F:KEY_CLIENTS", "P:U_9000006", "P:U_9000007", "P:U_9000008"],
  "data_gaps": ["Нет аналитики Альфа-Банка непосредственно по рынку топлива и запрета на экспорт бензина", "Нет данных о структуре закупочных контрактов и марже компании", "Нет данных о доле дизельного топлива в выручке — запрет касается только бензина"]
}
